function provisionalProviderTokens(platform: string, keyId: number, now: number): number {
  pruneLeases(now);
  let total = 0;
  for (const lease of leases.values()) {
    if (lease.platform === platform && lease.keyId === keyId) total += lease.tokens;
  }
  return total;
}

